interface Puller<T> {
  pull(max: number, timeoutMs: number, signal: AbortSignal): Promise<Message<T>[]>;
}

async function drain<T>(p: Puller<T>, signal: AbortSignal): Promise<void> {
  for (;;) {
    const batch = await p.pull(100, 500, signal);   // bounded batch + idle timeout
    if (batch.length === 0) { await backoff(signal); continue; }
    await handleAll(batch);                         // ack after handling
  }
}
